def count(n):
    total = 0
    for i in range(n):
        total += 1
    return total  # O(n)

def pairs(n):
    for i in range(n):
        for j in range(n):
            pass  # O(n^2)

def halve(n):
    while n > 1:
        n //= 2
    return n  # O(log n)

def fact(n):
    if n <= 1:
        return 1
    return n * fact(n - 1)

def merge_sort(a):
    if len(a) <= 1:
        return a
    m = len(a) // 2
    return merge(merge_sort(a[:m]), merge_sort(a[m:]))

def bt(path, options):
    if not options:
        return [list(path)]
    res = []
    for i, x in enumerate(options):
        res += bt(path + [x], options[:i] + options[i+1:])
    return res

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def powmod(b, e, m):
    r = 1
    while e:
        if e & 1:
            r = r * b % m
        b = b * b % m
        e >>= 1
    return r

def is_prime(n):
    if n < 2:
        return False
    i = 2
    while i * i <= n:
        if n % i == 0:
            return False
        i += 1
    return True

def popcount(n):
    c = 0
    while n:
        n &= n - 1
        c += 1
    return c

def single(nums):
    r = 0
    for x in nums:
        r ^= x
    return r

def neighbors(r, c, grid):
    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
            yield nr, nc

def reverse(a):
    i, j = 0, len(a) - 1
    while i < j:
        a[i], a[j] = a[j], a[i]
        i, j = i + 1, j - 1

def transpose(m):
    n = len(m)
    for i in range(n):
        for j in range(i + 1, n):
            m[i][j], m[j][i] = m[j][i], m[i][j]

def prefix(nums):
    pref = [0]
    for x in nums:
        pref.append(pref[-1] + x)
    return pref

def pref2d(grid):
    p = [[0] * (len(grid[0]) + 1) for _ in range(len(grid) + 1)]
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            p[i+1][j+1] = grid[i][j] + p[i][j+1] + p[i+1][j] - p[i][j]
    return p

def add(diff, l, r, v):
