def two_sum(a, target):
    i, j = 0, len(a) - 1
    while i < j:
        s = a[i] + a[j]
        if s == target:
            return (i, j)
        if s < target:
            i += 1
        else:
            j -= 1
    return None

def dedupe(a):
    w = 0
    for x in a:
        if w == 0 or a[w - 1] != x:
            a[w] = x
            w += 1
    return w

def is_pal(s):
    i, j = 0, len(s) - 1
    while i < j:
        if s[i] != s[j]:
            return False
        i, j = i + 1, j - 1
    return True

def length_of_longest(s):
    seen = {}
    left = 0
    best = 0
    for right, c in enumerate(s):
        if c in seen and seen[c] >= left:
            left = seen[c] + 1
        seen[c] = right
        best = max(best, right - left + 1)
    return best

def max_subarray(a):
    best = cur = a[0]
    for x in a[1:]:
        cur = max(x, cur + x)
        best = max(best, cur)
    return best

def max_subarray2(a):
    best = cur = 0
    for x in a:
        cur = max(0, cur + x)
        best = max(best, cur)
    return best

def max_circular(a):
    def kad(neg):
        best = cur = a[0] * neg
        for x in a[1:]:
            cur = max(x * neg, cur + x * neg)
            best = max(best, cur)
        return best
    straight = kad(1)
    wrapped = sum(a) + kad(-1)
    return max(straight, wrapped) if straight > 0 else straight

def three_sum_closest(a, t):
    a.sort()
    best = a[0] + a[1] + a[2]
    for i in range(len(a) - 2):
        lo, hi = i + 1, len(a) - 1
        while lo < hi:
            s = a[i] + a[lo] + a[hi]
            if abs(s - t) < abs(best - t):
                best = s
            if s < t:
                lo += 1
            else:
                hi -= 1
    return best

def merge(intervals):
    intervals.sort(key=lambda x: x[0])
    out = []
    for s, e in intervals:
        if not out or s > out[-1][1]:
            out.append([s, e])
        else:
            out[-1][1] = max(out[-1][1], e)
    return out

def kth_largest(a, k):
    a.sort()
    return a[-k]

def reverse_string(s):
    a = list(s)
    i, j = 0, len(a) - 1
    while i < j:
        a[i], a[j] = a[j], a[i]
        i, j = i + 1, j - 1
    return ''.join(a)

def compress(s):
    out = []
    i = 0
    while i < len(s):
        j = i
        while j < len(s) and s[j] == s[i]:
            j += 1
        out.append(s[i] + str(j - i))
        i = j
    return ''.join(out)

def counter(a):
    freq = {}
    for x in a:
        freq[x] = freq.get(x, 0) + 1
    return freq

def is_anagram(s, t):
    if len(s) != len(t):
        return False
    c = counter(s)
    for ch in t:
        c[ch] = c.get(ch, 0) - 1
        if c[ch] < 0:
            return False
    return True

def most_common(freq):
    best = None
    for x, c in freq.items():
        if best is None or c > freq[best]:
            best = x
    return best

def max_value(a):
    best = a[0]
    for x in a[1:]:
        if x > best:
            best = x
    return best

def compact_nonzero(a):
    w = 0
    for x in a:
        if x != 0:
            a[w] = x
            w += 1
    return a[:w]

def two_sum(nums, target):
    seen = {}
    for i, x in enumerate(nums):
        if target - x in seen:
            return [seen[target - x], i]
        seen[x] = i
    return []

def dedupe(a):
    seen = set()
    out = []
    for x in a:
        if x not in seen:
            seen.add(x)
            out.append(x)
    return out

def group_by_len(words):
    g = {}
    for w in words:
        g.setdefault(len(w), []).append(w)
    return g

def subarray_sum(nums, k):
    pref = 0
    counts = {0: 1}
    total = 0
    for x in nums:
        pref += x
        total += counts.get(pref - k, 0)
        counts[pref] = counts.get(pref, 0) + 1
    return total

def longest_sum_k(nums, k):
    first = {0: -1}
    pref = 0
    best = 0
    for i, x in enumerate(nums):
        pref += x
        if pref - k in first:
            best = max(best, i - first[pref - k])
        first.setdefault(pref, i)
    return best

def subarrays_divisible(nums, k):
    pref = 0
    rem = {0: 1}
    total = 0
    for x in nums:
        pref = (pref + x) % k
        total += rem.get(pref, 0)
        rem[pref] = rem.get(pref, 0) + 1
    return total

