def mode(a):
    from collections import Counter
    return Counter(a).most_common(1)[0][0]

from collections import defaultdict

def freq_default(nums):
    m = defaultdict(int)
    for x in nums:
        m[x] += 1
    return dict(m)

def same_letters(s, t):
    if len(s) != len(t):
        return False
    m = Counter(s)
    for ch in t:
        m[ch] -= 1
        if m[ch] < 0:
            return False
    return True

class ChainMap:
    def __init__(self, size=8):
        self.buckets = [[] for _ in range(size)]

    def _bucket(self, key):
        return self.buckets[hash(key) % len(self.buckets)]

    def put(self, key, val):
        b = self._bucket(key)
        for i, (k, v) in enumerate(b):
            if k == key:
                b[i] = (key, val)
                return
        b.append((key, val))

def probe_index(keys, start, size):
    i = start
    while keys[i] is not None:
        i = (i + 1) % size
    return i

def char_counts(s):
    m = {}
    for ch in s:
        m[ch] = m.get(ch, 0) + 1
    return m

def unique_ordered(a):
    seen = set()
    out = []
    for x in a:
        if x not in seen:
            seen.add(x)
            out.append(x)
    return out

def find_pair(a, target):
    seen = set()
    for x in a:
        if target - x in seen:
            return (target - x, x)
        seen.add(x)
    return None
